mapper.select:
select #{name} as finprodName, ti.A1,/**应税利息及红利收入-不含税*/ ti.B1,/**利息及红利收入增值税*/ ti.A2,/**金融商品转让损益*/ ti.B2,/**金融商品转让增值税*/ ti.B3,/**金融商品转让入账增值税*/ ti.FREE_36FILE,/**免税收入-36号文件*/ ti.FREE_46FILE,/**免税收入-46号文件*/ ti.FREE_70FILE,/**免税收入-70号文件*/ ti.FREE_SEC,/**免税收入-国债及地方债*/ ti.C1,/**本期应交增值税产品划转到银行增值税*/ ti.C2,/**本期应交附加税费产品划转到银行附加税费*/ ti.C3,/**本期应交增值税银行划转到税局金融商品转让增值税*/ ti.C4,/**本期应交增值税银行划转到税局增值税*/ ti.C5,/**本期应交附加税费银行划转到税局附加税费*/ ti.E1,/**本期留存收益变动额*/ ti.E2,/**期初留存收益*/ ti.E3/**期末留存收益*/ from TAX_DECLARE_SUM_INFO ti left join BOK_BOOKSET bb on bb.bookset_id = ti.SUBJECT_NATURE left join FIN_PRODUCT fp on fp.finprod_id = bb.ACCT_SUBJECT_ID where 1=1
and DATE_FORMAT(ti.DECLARE_YEAR,'%Y') = #{declarYear}
and ti.DECLARE_DATE = #{declarDate}
and ti.DECLARE_TYPE = #{sumDimen}
